-- V1.3.1 (docs/v131/lot1-securite.md, D11, second half). public.titan_find_profile_by_friend_code had no rate limit: a signed-in
-- account could walk the friend-code space and list every public profile. The body is the one of 20261102130000, unchanged, with
-- the project's shared limiter in front (30 lookups per account and hour, PT429 RATE_LIMITED beyond, as for the other social
-- RPCs). The limiter writes an event, so the function becomes VOLATILE. Signature, return shape and grants are unchanged; no
-- client calls it today (friend requests go through titan_social_request).
-- The caller owns the transaction: never BEGIN/COMMIT here.
-- Rollback: re-create the function from 20261102130000 (STABLE, without the perform line).

CREATE OR REPLACE FUNCTION public.titan_find_profile_by_friend_code(p_friend_code text)
 RETURNS TABLE(id uuid, username text, friend_code text, level integer, avatar text, is_elite boolean, is_suspended boolean)
 LANGUAGE plpgsql
 VOLATILE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '42501';
  end if;
  perform private.titan_rate_limit(auth.uid(), 'friend_code_lookup', 30);

  return query
  select p.id, p.username, p.friend_code,
    case when coalesce((p.privacy->>'showStats')::boolean, false) then p.level else 1 end,
    p.avatar, p.is_elite, p.is_suspended
  from public.profiles p
  where p.friend_code = upper(trim(p_friend_code))
    and coalesce((p.privacy->>'publicProfile')::boolean, false)
    and not coalesce(p.is_suspended, false)
    and not exists (
      select 1 from public.titan_user_blocks b
      where (b.blocker_id = auth.uid() and b.blocked_id = p.id)
         or (b.blocker_id = p.id and b.blocked_id = auth.uid())
    )
  limit 1;
end;
$function$
;
